usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Conversations.New(
		context.TODO(),
		openai.ConversationNewParams{
			Metadata: map[string]string{"key": "string"},
			Items: []openai.InputItem{openai.EasyInputMessage{Role: openai.EasyInputMessageRoleUser, Content: "string", Phase: openai.MessagePhaseCommentary, Type: "message"}},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
